import sys, os, ast
TARGETS = [os.path.abspath("dateutil/"+f) for f in ("relativedelta.py","rrule.py")]
hits = {t:set() for t in TARGETS}
def tracer(frame, event, arg):
    if event == 'line':
        fn = frame.f_code.co_filename
        if fn in hits: hits[fn].add(frame.f_lineno)
    return tracer
sys.settrace(tracer)
import pytest
rc = pytest.main(["dateutil/test", "-q", "-p", "no:cacheprovider"])
sys.settrace(None)
for t in TARGETS:
    src = open(t).read().splitlines()
    tree = ast.parse("\n".join(src))
    executable = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.stmt) and not isinstance(node, (ast.FunctionDef, ast.ClassDef, ast.AsyncFunctionDef)):
            executable.add(node.lineno)
    unc = sorted(executable - hits[t])
    print("=== %s : %d/%d executable lines uncovered ===" % (os.path.basename(t), len(unc), len(executable)))
    for ln in unc:
        print("%5d: %s" % (ln, src[ln-1]))
