cd /tmp/mut && python3 - <<'EOF' 2>/dev/null
import sys, io, unittest, time
sys.path.insert(0,'/tmp/mut'); sys.path.insert(0,'/tmp')
from battery import battery
SRC='/tmp/mut/dateutil/relativedelta.py'
ORIG=open(SRC).read()
def run_tests():
    for m in list(sys.modules):
        if m.startswith('dateutil'): del sys.modules[m]
    try:
        import dateutil.test.test_relativedelta as t
        s=unittest.defaultTestLoader.loadTestsFromModule(t)
        res=unittest.TextTestRunner(stream=io.StringIO(),verbosity=0).run(s)
        return res.wasSuccessful() and res.testsRun==62
    except Exception: return False
def load_rd():
    for m in list(sys.modules):
        if m.startswith('dateutil'): del sys.modules[m]
    import dateutil.relativedelta as r
    return r
open(SRC,'w').write(ORIG)
base=battery(load_rd()); assert run_tests()
lines=ORIG.split('\n')
cands=[]
for i in range(len(lines)):
    if not lines[i].strip(): continue
    l2=lines[:i]+lines[i+1:]
    open(SRC,'w').write('\n'.join(l2))
    if run_tests():
        try: b=battery(load_rd())
        except Exception as e: b={'ERR':str(e)}
        diffs={k:(base[k],b.get(k)) for k in base if base.get(k)!=b.get(k)}
        cands.append((i+1,lines[i].strip(),diffs))
open(SRC,'w').write(ORIG)
print("deletion mutants passing tests:",len(cands))
for ln,txt,diffs in cands:
    print("DEL line %d: %s  diffs=%d"%(ln,txt,len(diffs)))
    for k,(a,b) in list(diffs.items())[:6]:
        print("     %-20s orig=%s mut=%s"%(k,a,b))
